// Regenerates extension/src/lib/psl.js from the official Public Suffix List.
//
//   node tools/build-psl.mjs                  # download https://publicsuffix.org/list/public_suffix_list.dat
//   node tools/build-psl.mjs --file list.dat  # or use a local copy (offline)
//
// The extension never touches the network for this: the list is baked into psl.js at
// development time, so refreshing it is a deliberate commit (do it every few months).
//
// Compaction: single-label rules (".com", ".uk"...) are dropped — the PSL's implicit
// default rule ("*") already treats any unknown last label as a public suffix, and
// nothing changes for them. Only rules with 2+ labels (and exceptions) need data.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, domainToASCII } from 'node:url';

const SOURCE = 'https://publicsuffix.org/list/public_suffix_list.dat';
const out = path.join(path.dirname(fileURLToPath(import.meta.url)), '../../extension/src/lib/psl.js');

const fileArg = process.argv.indexOf('--file');
const raw = fileArg > -1
  ? fs.readFileSync(process.argv[fileArg + 1], 'utf8')
  : await (async () => {
    const res = await fetch(SOURCE);
    if (!res.ok) throw new Error(`${SOURCE}: HTTP ${res.status}`);
    return res.text();
  })();

const version = (raw.match(/^\/\/ VERSION: (.+)$/m) || [])[1] || 'unknown';
const commit = (raw.match(/^\/\/ COMMIT: (.+)$/m) || [])[1] || 'unknown';

const rules = [];
for (const line of raw.split(/\r?\n/)) {
  const rule = line.trim().split(/\s+/)[0];
  if (!rule || rule.startsWith('//')) continue;
  if (rule.includes('`') || rule.includes('${')) throw new Error(`unsafe rule: ${rule}`);
  // keep: any exception, any wildcard, and normal rules with 2+ labels
  if (!(rule.startsWith('!') || rule.startsWith('*.') || rule.includes('.'))) continue;
  // URL.hostname is punycode, so store the rules the same way ("公司.cn" -> "xn--55qx5d.cn").
  const prefix = rule.startsWith('!') ? '!' : rule.startsWith('*.') ? '*.' : '';
  const ascii = domainToASCII(rule.slice(prefix.length));
  if (!ascii) throw new Error(`cannot convert rule to punycode: ${rule}`);
  rules.push(prefix + ascii);
}
const unique = [...new Set(rules)].sort();
rules.length = 0;
rules.push(...unique);

const body = `// GENERATED by dist/tools/build-psl.mjs — do not edit by hand.
//
// Public Suffix List (https://publicsuffix.org/), (c) the PSL authors, licensed under
// the Mozilla Public License 2.0 (https://mozilla.org/MPL/2.0/).
// List version: ${version}
// List commit:  ${commit}
//
// One rule per line: "a.b" = suffix, "*.a.b" = wildcard, "!x.a.b" = exception.
// Single-label rules are omitted (the PSL's implicit "*" default covers them).

export const PSL_VERSION = ${JSON.stringify(version)};
export const PSL_RULES = \`
${rules.join('\n')}
\`;
`;
fs.writeFileSync(out, body);
const kb = (Buffer.byteLength(body) / 1024).toFixed(0);
console.log(`wrote ${path.relative(process.cwd(), out)} — ${rules.length} rules, ${kb} KB, list version ${version}`);
